'use strict';
const $=id=>document.getElementById(id),KEY='giorno-v1';let data={version:1,blocks:[],inbox:[]},storageOK=true,pendingThought=null,installPrompt=null,slotTaskId=null,currentSlots=[];
const dateOf=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>dateOf(new Date());const plus=(d,n)=>{const x=new Date(d+'T12:00:00');x.setDate(x.getDate()+n);return dateOf(x);};const min=t=>Number(t.slice(0,2))*60+Number(t.slice(3));const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const validDate=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&s>='2020-01-01'&&s<='2100-12-31'&&!isNaN(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s;
const validTime=s=>typeof s==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(s);
function valid(v){return v&&v.version===1&&Array.isArray(v.blocks)&&Array.isArray(v.inbox)&&v.blocks.length<=10000&&v.inbox.length<=10000&&new Set([...v.blocks,...v.inbox].map(x=>x.id)).size===v.blocks.length+v.inbox.length&&v.blocks.every(x=>typeof x.id==='string'&&/^[\w-]{1,80}$/.test(x.id)&&typeof x.title==='string'&&x.title.trim().length>0&&x.title.length<=140&&validDate(x.date)&&validTime(x.start)&&validTime(x.end)&&min(x.end)>min(x.start)&&['task','fixed','break'].includes(x.kind)&&typeof x.done==='boolean'&&typeof x.important==='boolean')&&v.inbox.every(x=>typeof x.id==='string'&&/^[\w-]{1,80}$/.test(x.id)&&typeof x.title==='string'&&x.title.trim().length>0&&x.title.length<=140&&validFlex(x));}
try{const s=localStorage.getItem(KEY);if(s){const v=JSON.parse(s);if(!valid(v))throw Error('invalid');data=v;}}catch{storageOK=false;$('error').hidden=false;$('error').textContent='Non riesco a leggere i dati salvati. Esporta ciò che vedi prima di ripristinare un backup. Le modifiche sono sospese per non sovrascrivere il programma.';}
$('date').value=today();$('date').min='2020-01-01';$('date').max='2100-12-31';
function message(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(message.timer);message.timer=setTimeout(()=>$('toast').hidden=true,3500);}
function commit(next){if(!storageOK){message('Salvataggio non disponibile. Ripristina un backup valido.');return false;}try{localStorage.setItem(KEY,JSON.stringify(next));data=next;render();return true;}catch{message('Non è stato possibile salvare. Esporta un backup e libera spazio nel browser.');return false;}}
function render(){const day=$('date').value,blocks=data.blocks.filter(b=>b.date===day).sort((a,b)=>a.start.localeCompare(b.start)),priority=blocks.find(b=>b.important),done=blocks.filter(b=>b.done).length,total=blocks.reduce((s,b)=>s+min(b.end)-min(b.start),0);
$('priorityTitle').textContent=priority?priority.title:'Scegli una sola priorità.';$('priorityHint').textContent=priority?(priority.done?'Fatta. Puoi riconoscere anche questo risultato.':`${priority.start} – ${priority.end} · Il resto può aspettare questo spazio.`):'Quando aggiungi un blocco, indica quello più importante.';
$('summary').textContent=blocks.length?`${blocks.length} ${blocks.length===1?'blocco':'blocchi'} · ${Math.floor(total/60)} h ${total%60?total%60+' min':''} programmate · ${done} completati`:'Lascia spazio anche agli imprevisti.';
let html='',until=0;blocks.forEach(b=>{const gap=min(b.start)-until;if(until&&gap>0)html+=`<div class="free">${gap} minuti liberi</div>`;until=Math.max(until,min(b.end));html+=`<article class="block"><div class="time">${b.start}<span>${b.end}</span></div><div class="card ${b.kind} ${b.done?'done':''}"><button class="donebutton" data-act="done" data-id="${esc(b.id)}" aria-label="${b.done?'Segna da fare':'Completa'}: ${esc(b.title)}" aria-pressed="${b.done}">${b.done?'✓':''}</button><div class="card-content"><span class="tag">${b.important?'★ Priorità · ':''}${({task:'Da fare',fixed:'Impegno fisso',break:'Pausa'})[b.kind]}</span><strong>${esc(b.title)}</strong><div class="actions"><button data-act="edit" data-id="${esc(b.id)}">Modifica</button><button data-act="move" data-id="${esc(b.id)}">Sposta</button></div></div></div></article>`;});
$('timeline').innerHTML=html||'<div class="empty"><h3>Da cosa cominciamo?</h3><p>Metti in programma un impegno e una cosa che conta. Il resto può prendere forma dopo.</p><button class="primary" data-act="new">＋ Crea il primo blocco</button></div>';
$('closingText').textContent=done?`${done} ${done===1?'cosa completata':'cose completate'}. Quello che resta si può riprogrammare.`:'Le cose rimaste si possono riprogrammare, una alla volta.';
renderFlexible();}

function openEditor(b,thought){pendingThought=thought?.id||null;$('blockform').reset();$('itemId').value=b?.id||'';$('title').value=b?.title||thought?.title||'';$('blockDate').value=b?.date||$('date').value;$('start').value=b?.start||'09:00';$('end').value=b?.end||'09:30';$('kind').value=b?.kind||'task';$('important').checked=!!b?.important;$('formError').textContent='';$('delete').hidden=!b;$('editor').showModal();}
$('blockform').onsubmit=e=>{e.preventDefault();const old=data.blocks.find(x=>x.id===$('itemId').value),b={id:old?.id||crypto.randomUUID(),title:$('title').value.trim(),date:$('blockDate').value,start:$('start').value,end:$('end').value,kind:$('kind').value,important:$('important').checked,done:old?.done||false};if(!valid({version:1,blocks:[b],inbox:[]})){$('formError').textContent='Controlla il titolo e scegli una fine successiva all’inizio, nello stesso giorno.';return;}if(pendingThought){const source=data.inbox.find(x=>x.id===pendingThought);if(!source){$('formError').textContent='Questo impegno non è più nella lista. Chiudi e aggiorna il programma.';return;}const t=GiornoSlots.defaults(source);if(t.waiting||t.deadline&&b.date>t.deadline||t.after&&b.date<t.after||!t.days.includes(new Date(b.date+'T12:00:00').getDay())||min(b.start)<min(t.from)||min(b.end)>min(t.to)||min(b.end)-min(b.start)<t.duration){$('formError').textContent='Questo orario non rispetta durata, disponibilità o scadenza. Modifica prima i dettagli nella lista se sono cambiati.';return;}}const conflict=data.blocks.find(x=>x.id!==b.id&&x.date===b.date&&min(x.start)<min(b.end)&&min(b.start)<min(x.end));if(conflict){$('formError').textContent=`Questo spazio si sovrappone a “${conflict.title}” (${conflict.start}–${conflict.end}). Scegli un altro orario.`;return;}const next=structuredClone(data);next.blocks=next.blocks.filter(x=>x.id!==b.id).map(x=>b.important&&x.date===b.date?{...x,important:false}:x);next.blocks.push(b);if(pendingThought)next.inbox=next.inbox.filter(x=>x.id!==pendingThought);if(commit(next)){$('date').value=b.date;render();$('editor').close();message('Blocco salvato');}};
$('delete').onclick=()=>{if(confirm('Eliminare questo blocco dal programma?')){const next=structuredClone(data);next.blocks=next.blocks.filter(x=>x.id!==$('itemId').value);if(commit(next))$('editor').close();}};
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.close){$(t.dataset.close).close();return;}const {act,id}=t.dataset;if(!act)return;const b=data.blocks.find(x=>x.id===id);if(act==='new')openEditor();if(act==='edit'&&b)openEditor(b);if(act==='move'&&b){openEditor(b);$('blockDate').value=plus(b.date,1);$('formTitle').textContent='Scegli un nuovo spazio';}if(act==='done'&&b){const n=structuredClone(data);n.blocks.find(x=>x.id===id).done=!b.done;commit(n);}if(act==='plan')showSlots(data.inbox.find(x=>x.id===id));if(act==='removeThought'&&confirm('Eliminare questa cosa dalla lista?')){const n=structuredClone(data);n.inbox=n.inbox.filter(x=>x.id!==id);commit(n);}});
$('editor').addEventListener('close',()=>$('formTitle').textContent='Un blocco per la tua giornata');
$('add').onclick=()=>openEditor();$('quick').onsubmit=e=>{e.preventDefault();const title=$('thought').value.trim();if(!title)return;const n=structuredClone(data);n.inbox.push({id:crypto.randomUUID(),title});if(commit(n))$('thought').value='';};
function day(d){if(validDate(d)){$('date').value=d;render();}}$('prev').onclick=()=>day(plus($('date').value,-1));$('next').onclick=()=>day(plus($('date').value,1));$('today').onclick=()=>day(today());$('tomorrow').onclick=$('prepare').onclick=()=>day(plus(today(),1));$('date').onchange=()=>{if(!validDate($('date').value))$('date').value=today();render();};$('help').onclick=()=>$('guide').showModal();
function download(content,type,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('backup').onclick=()=>download(JSON.stringify(data,null,2),'application/json',`giorno-backup-${today()}.json`);$('restore').onclick=()=>$('backupFile').click();$('backupFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error();const v=JSON.parse(await f.text());if(!valid(v))throw Error();if(confirm('Il backup sostituirà il programma presente in questo browser. Continuare?')){localStorage.setItem(KEY,JSON.stringify(v));data=v;storageOK=true;$('error').hidden=true;render();message('Backup ripristinato');}}catch{message('Backup non valido o salvataggio non disponibile. Il programma non è stato sostituito.');}e.target.value='';};
function foldLine(s){let out='',count=0;for(const c of s){const n=new TextEncoder().encode(c).length;if(count+n>74){out+='\r\n ';count=1;}out+=c;count+=n;}return out;}
const ical=s=>s.replace(/\\/g,'\\\\').replace(/\r\n|\r|\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
$('calendar').onclick=()=>{const blocks=data.blocks.filter(x=>x.date===$('date').value&&!x.done);if(!blocks.length){message('Aggiungi prima un blocco da fare in questa giornata.');return;}const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Giorno//Planner//IT','CALSCALE:GREGORIAN'];for(const b of blocks)lines.push('BEGIN:VEVENT','UID:'+b.id+'@giorno.local','DTSTAMP:'+stamp,'DTSTART:'+b.date.replaceAll('-','')+'T'+b.start.replace(':','')+'00','DTEND:'+b.date.replaceAll('-','')+'T'+b.end.replace(':','')+'00','SUMMARY:'+ical(b.title),'BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:'+ical(b.title),'END:VALARM','END:VEVENT');lines.push('END:VCALENDAR');download(lines.map(foldLine).join('\r\n')+'\r\n','text/calendar;charset=utf-8',`giorno-${$('date').value}.ics`);message('Importa il file nel calendario e controlla gli avvisi.');};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;}else $('installDialog').showModal();};
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const v=JSON.parse(e.newValue);if(valid(v)){data=v;render();}}catch{}}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_block_creation',description:'Apre il modulo per programmare un blocco. Non salva il programma.',inputSchema:{type:'object',properties:{title:{type:'string',maxLength:140}},required:['title'],additionalProperties:false},execute:v=>{if(!v||typeof v.title!=='string'||!v.title.trim()||v.title.length>140)throw Error('Titolo non valido');openEditor(null,{title:v.title});return {opened:true};}})).catch(()=>{});}catch{}}
function validFlex(x){return (x.duration===undefined||Number.isInteger(x.duration)&&x.duration>=5&&x.duration<=720&&x.duration%5===0)&&(x.from===undefined||validTime(x.from))&&(x.to===undefined||validTime(x.to))&&(x.days===undefined||Array.isArray(x.days)&&x.days.length>0&&x.days.length<=7&&x.days.every(d=>Number.isInteger(d)&&d>=0&&d<=6))&&(!x.deadline||validDate(x.deadline))&&(!x.after||validDate(x.after))&&(x.waiting===undefined||typeof x.waiting==='boolean')&&(x.prerequisite===undefined||typeof x.prerequisite==='string'&&x.prerequisite.length<=140);}
function niceDate(d){return new Date(d+'T12:00:00').toLocaleDateString('it-IT',{weekday:'short',day:'numeric',month:'short'});}
function renderFlexible(){
 const sorted=[...data.inbox].sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999'));
 $('inboxCount').textContent=sorted.length;
 $('pendingSummary').hidden=!sorted.length;$('pendingSummary').textContent=`${sorted.length} ${sorted.length===1?'impegno da incastrare':'impegni da incastrare'} · Guarda cosa può trovare spazio →`;
 $('inboxList').innerHTML=sorted.map(raw=>{const t=GiornoSlots.defaults(raw),due=t.deadline?(t.deadline<today()?'Scadenza passata · rivedi la data':`Entro ${niceDate(t.deadline)}`):'Senza scadenza';return `<article class="thought"><span>${esc(t.title)}</span><p class="details">${t.duration} min · ${t.from}–${t.to}</p><p class="details deadline">${esc(due)}</p>${t.after&&t.after>today()?`<p class="details">Da riprendere ${niceDate(t.after)}</p>`:''}${t.waiting?`<p class="waiting-note">In attesa${t.prerequisite?': '+esc(t.prerequisite):' di un primo passo o di una risposta'}</p>`:''}<div class="thought-actions">${t.waiting?`<button data-act="ready" data-id="${t.id}">Ora posso farlo</button>`:`<button class="find-space" data-act="plan" data-id="${t.id}">Trova spazio →</button>`}<button data-act="flexEdit" data-id="${t.id}">Dettagli</button><button data-act="removeThought" data-id="${t.id}" aria-label="Elimina ${esc(t.title)}">Elimina</button></div></article>`;}).join('');
}
function editFlexible(raw){const t=GiornoSlots.defaults(raw||{});$('flexForm').reset();$('flexId').value=t.id||'';$('flexTitle').value=t.title||'';$('duration').value=t.duration;$('availableFrom').value=t.from;$('availableTo').value=t.to;$('deadline').value=t.deadline;$('waiting').checked=t.waiting;$('prerequisite').value=t.prerequisite;document.querySelectorAll('[name=weekday]').forEach(x=>x.checked=t.days.includes(Number(x.value)));$('flexError').textContent='';$('flexEditor').showModal();}
function showSlots(t){if(!t)return;slotTaskId=t.id;$('slotTitle').textContent=t.title;refreshSlots();$('slotDialog').showModal();}
function refreshSlots(){const t=data.inbox.find(x=>x.id===slotTaskId);if(!t){$('slotDialog').close();return;}const f=GiornoSlots.defaults(t);currentSlots=GiornoSlots.findSlots(t,data.blocks,$('date').value);$('slotInfo').textContent=`${f.duration} minuti · ${f.from}–${f.to}${f.deadline?' · entro '+niceDate(f.deadline):' · senza scadenza'}`;$('slotChoices').innerHTML=currentSlots.length?currentSlots.map((s,i)=>`<div class="slot"><div><b>${niceDate(s.date)}</b><span>${s.start} – ${s.end}</span></div><button class="primary" data-slot="${i}">Mettila qui</button></div>`).join(''):`<p class="slot-empty">${f.waiting?'Prima risolvi il vincolo indicato nei dettagli.':f.deadline&&f.deadline<today()?'La scadenza è passata. Rivedi la data nei dettagli oppure togli la scadenza.':'Non ho trovato uno spazio compatibile entro la scadenza o nei prossimi 14 giorni. Puoi cambiare disponibilità o scegliere una data più avanti.'} L’impegno resta nella lista.</p>`;}
$('addFlexible').onclick=()=>editFlexible();$('pendingSummary').onclick=()=>{$('addFlexible').scrollIntoView({behavior:'smooth',block:'center'});$('addFlexible').focus({preventScroll:true});};
$('flexForm').onsubmit=e=>{e.preventDefault();const old=data.inbox.find(x=>x.id===$('flexId').value);const t={...GiornoSlots.defaults(old||{}),id:old?.id||crypto.randomUUID(),title:$('flexTitle').value.trim(),duration:Number($('duration').value),from:$('availableFrom').value,to:$('availableTo').value,days:[...document.querySelectorAll('[name=weekday]:checked')].map(x=>Number(x.value)),deadline:$('deadline').value,waiting:$('waiting').checked,prerequisite:$('prerequisite').value.trim()};if(!validFlex(t)||!t.title||min(t.to)-min(t.from)<t.duration){$('flexError').textContent='Scegli almeno un giorno e una fascia oraria abbastanza lunga per la durata indicata.';return;}const n=structuredClone(data);n.inbox=n.inbox.filter(x=>x.id!==t.id);n.inbox.push(t);if(commit(n)){$('flexEditor').close();message('Impegno conservato nella lista');}};
$('slotLater').onclick=()=>{const n=structuredClone(data),t=n.inbox.find(x=>x.id===slotTaskId);if(!t)return;t.after=plus(today(),1);if(commit(n)){$('slotDialog').close();message('Resta nella lista. Cercherò spazio da domani, quando apri l’app.');}};
$('slotManual').onclick=()=>{const t=data.inbox.find(x=>x.id===slotTaskId);if(!t)return;$('slotDialog').close();openEditor(null,t);const s=currentSlots[0];if(s){$('blockDate').value=s.date;$('start').value=s.start;$('end').value=s.end;}else{$('start').value=GiornoSlots.defaults(t).from;$('end').value=GiornoSlots.defaults(t).to;}};
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;const {act,id}=button.dataset;const t=data.inbox.find(x=>x.id===id);if(act==='flexEdit'&&t)editFlexible(t);if(act==='ready'&&t){const n=structuredClone(data);n.inbox.find(x=>x.id===id).waiting=false;commit(n);}if(button.dataset.slot!==undefined){const t=data.inbox.find(x=>x.id===slotTaskId),s=currentSlots[Number(button.dataset.slot)];if(!t||!s)return;const fresh=GiornoSlots.findSlots(t,data.blocks,$('date').value);if(!fresh.some(x=>x.date===s.date&&x.start===s.start&&x.end===s.end)){refreshSlots();message('La disponibilità è cambiata. Scegli una nuova proposta.');return;}const n=structuredClone(data);n.blocks.push({id:crypto.randomUUID(),title:t.title,...s,kind:'task',important:false,done:false});n.inbox=n.inbox.filter(x=>x.id!==t.id);if(commit(n)){$('slotDialog').close();day(s.date);message('Impegno inserito nel programma');}}});

render();
